from typing import Iterable, Iterator, TypeVar, List

T = TypeVar('T')

def chunk_list(seq: List[T], n: int) -> Iterator[List[T]]:
    if n <= 0:
        raise ValueError('n must be positive')
    for i in range(0, len(seq), n):
        yield seq[i:i + n]
```
