import time
import functools
from typing import Callable, Type, Tuple

def retry_with_backoff(
    retries: int = 3,
    base_delay: float = 0.5,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
) -> Callable:
    def decorator(fn: Callable) -> Callable:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(retries + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == retries:
                        raise
                    time.sleep(base_delay * (2 ** attempt))
        return wrapper
    return decorator
```
Sleep doubles each attempt: 0.5s, 1s, 2s. Re-raises after the final try fails.

```python
import time, random, functools
from typing import Callable, Type, Tuple

def retry_with_backoff(
    retries: int = 3,
    base_delay: float = 0.5,
    exceptions: Tuple[Type[BaseException], ...] = (Exception,),
) -> Callable:
    def decorator(fn: Callable) -> Callable:
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(retries + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == retries:
                        raise
                    delay = base_delay * (2 ** attempt)
                    time.sleep(delay * (0.5 + random.random()))
        return wrapper
    return decorator
```
Multiplying by `0.5 + random()` spreads retries across [0.5x, 1.5x] of the nominal delay so a fleet of clients does not synchronize.

