from typing import Any, Dict

def unflatten_dict(d: Dict[str, Any], sep: str = '.') -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for flat_key, value in d.items():
        parts = flat_key.split(sep)
        cur = out
        for p in parts[:-1]:
            cur = cur.setdefault(p, {})
        cur[parts[-1]] = value
    return out
```
