from typing import List

def bin_packing_first_fit(sizes: List[int], capacity: int) -> List[List[int]]:
    if any(s > capacity for s in sizes):
        raise ValueError('item larger than bin capacity')
    bins: List[List[int]] = []
    bin_remaining: List[int] = []
    for s in sorted(sizes, reverse=True):
        for i, rem in enumerate(bin_remaining):
            if s <= rem:
                bins[i].append(s)
                bin_remaining[i] -= s
                break
        else:
            bins.append([s])
            bin_remaining.append(capacity - s)
    return bins
```
First-fit decreasing is a well-known approximation that uses at most 11/9 OPT + 6/9 bins. Sorting big items first helps a lot.

