def memoize(fn: Callable) -> Callable:
    cache: Dict[Tuple[Any, ...], Any] = {}
    @functools.wraps(fn)
    def wrapper(*args):
        if args not in cache:
            cache[args] = fn(*args)
        return cache[args]
    wrapper.cache = cache  # type: ignore[attr-defined]
    return wrapper
