from collections import deque
from typing import Iterable, List

def running_max(values: Iterable[float], window: int) -> List[float]:
    if window <= 0:
        raise ValueError('window must be positive')
    dq: deque[int] = deque()
    out: List[float] = []
    values = list(values)
    for i, v in enumerate(values):
        while dq and values[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - window:
            dq.popleft()
        if i >= window - 1:
            out.append(values[dq[0]])
    return out
```
Monotonic deque trick: kick out indices that can never be the max again. Each index enters and leaves at most once, giving O(n).

