from collections import deque
from typing import Dict, List, Hashable, TypeVar

T = TypeVar('T', bound=Hashable)

def topological_sort(graph: Dict[T, List[T]]) -> List[T]:
    indeg: Dict[T, int] = {n: 0 for n in graph}
    for deps in graph.values():
        for d in deps:
            indeg[d] = indeg.get(d, 0) + 1
    queue: deque[T] = deque(n for n, d in indeg.items() if d == 0)
    out: List[T] = []
    while queue:
        n = queue.popleft()
        out.append(n)
        for d in graph.get(n, []):
            indeg[d] -= 1
            if indeg[d] == 0:
                queue.append(d)
    if len(out) != len(indeg):
        raise ValueError('graph has a cycle')
    return out
```
Kahn's algorithm: repeatedly pop zero-indegree nodes. The final length check detects cycles.

```python
from typing import Dict, List, Hashable, TypeVar

T = TypeVar('T', bound=Hashable)

def topological_sort_dfs(graph: Dict[T, List[T]]) -> List[T]:
    WHITE, GRAY, BLACK = 0, 1, 2
    color: Dict[T, int] = {n: WHITE for n in graph}
    out: List[T] = []
    def visit(n: T) -> None:
        if color[n] == GRAY:
            raise ValueError('cycle detected')
        if color[n] == BLACK:
            return
        color[n] = GRAY
        for d in graph.get(n, []):
            visit(d)
        color[n] = BLACK
        out.append(n)
    for n in graph:
        visit(n)
    return out[::-1]
```
DFS naturally produces a reverse-postorder topological list. Cycle detection falls out of seeing a GRAY node.

