import heapq
from typing import List

class RunningMedian:
    def __init__(self) -> None:
        self.lo: List[float] = []  # max-heap (negated)
        self.hi: List[float] = []  # min-heap

    def add(self, value: float) -> None:
        if not self.lo or value <= -self.lo[0]:
            heapq.heappush(self.lo, -value)
        else:
            heapq.heappush(self.hi, value)
        if len(self.lo) > len(self.hi) + 1:
            heapq.heappush(self.hi, -heapq.heappop(self.lo))
        elif len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))

    def median(self) -> float:
        if not self.lo:
            raise ValueError('no values yet')
        if len(self.lo) > len(self.hi):
            return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2
```
Lower half in a max-heap (negated since heapq is min-only), upper half in a min-heap. Each `add` is O(log n).

