def memo_with_ttl(ttl: float) -> Callable:
    def decorator(fn: Callable) -> Callable:
        cache: Dict[Tuple[Any, ...], Tuple[float, Any]] = {}
        @functools.wraps(fn)
        def wrapper(*args):
            now = time.monotonic()
            if args in cache:
                ts, val = cache[args]
                if now - ts < ttl:
                    return val
            val = fn(*args)
            cache[args] = (now, val)
            return val
        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper
    return decorator
