from typing import Any, Dict

def dict_diff_deep(a: Dict[str, Any], b: Dict[str, Any], path: str = '') -> Dict[str, Any]:
    diff: Dict[str, Any] = {'added': {}, 'removed': {}, 'changed': {}}
    for k in b.keys() - a.keys():
        diff['added'][f'{path}{k}'] = b[k]
    for k in a.keys() - b.keys():
        diff['removed'][f'{path}{k}'] = a[k]
    for k in a.keys() & b.keys():
        if isinstance(a[k], dict) and isinstance(b[k], dict):
            sub = dict_diff_deep(a[k], b[k], f'{path}{k}.')
            for cat in ('added','removed','changed'):
                diff[cat].update(sub[cat])
        elif a[k] != b[k]:
            diff['changed'][f'{path}{k}'] = (a[k], b[k])
    return diff
```
