        raise ValueError('target must be non-negative')
    INF = float('inf')
    dp = [0] + [INF] * target
    for amt in range(1, target + 1):
        for c in denominations:
            if c <= amt and dp[amt - c] + 1 < dp[amt]:
                dp[amt] = dp[amt - c] + 1
