    @lru_cache(maxsize=None)
    def helper(amt: int) -> int:
        if amt == 0:
            return 0
        if amt < 0:
            return -1
        best = -1
        for c in denominations:
            sub = helper(amt - c)
            if sub != -1 and (best == -1 or sub + 1 < best):
                best = sub + 1
        return best
    return helper(target)
```
